import React from 'react';
import { Box, Heading, Image, Text } from '@salesforce/retail-react-app/app/components/shared/ui';

export type ImageTextProps = {
  /** @cf Image, media */
  image?: string;
  /** @cf Image Alt Text */
  imageAlt?: string;
  /** @cf Headline */
  headline?: string;
  /** @cf Body, longText */
  body?: string;
  /** @cf Image Position, select, left */
  imagePosition?: 'left' | 'right';
};

/** @cf-register */
const ImageText = ({ image, imageAlt = '', headline, body, imagePosition = 'left' }: ImageTextProps) => (
  <Box
    display="flex"
    flexDirection={{ base: 'column', md: imagePosition === 'right' ? 'row-reverse' : 'row' }}
    alignItems="center"
    gap={8}
    px={8}
    py={12}
    maxW="container.xl"
    mx="auto"
  >
    {image && (
      <Box flex="1">
        <Image src={image} alt={imageAlt} w="100%" objectFit="cover" loading="lazy" />
      </Box>
    )}
    <Box flex="1">
      {headline && (
        <Heading as="h2" size="xl" mb={4}>
          {headline}
        </Heading>
      )}
      {body && <Text fontSize="lg">{body}</Text>}
    </Box>
  </Box>
);

export default ImageText;

